// The Downex logo for the extension pages (docs/DESIGN-SYSTEM.md §2.6.4): the app icon of
// internal/brand, a "D" made of four download segments, square on the left and round on the
// right, whose third bar is split with its last chunk still arriving. The same in both themes (it
// is also the toolbar icon, ext/public/icon/*, generated by ui/build/genicon.go). Laid out like
// internal/brand's appTile and fit, snapped to whole pixels at every size so that small marks stay
// sharp; the desktop's BrandMark.svelte follows the same rules.

export interface BrandBar {
  readonly x: number;
  readonly y: number;
  readonly w: number;
  readonly h: number;
  /** Radius of the round right end (0: square). */
  readonly r: number;
  /** The live chunk. */
  readonly head: boolean;
}

export interface BrandLayout {
  /** The tile's square, in pixels. */
  readonly x0: number;
  readonly x1: number;
  readonly radius: number;
  /** Width of the hairline edge (0: none, below 32 px). */
  readonly hairline: number;
  readonly bars: readonly BrandBar[];
}

/** The bars on the pixel grid at `u` pixels per master unit (internal/brand fit). */
function fit(size: number, u: number): BrandBar[] {
  let h = Math.max(1, Math.round(24 * u));
  let g = Math.max(1, Math.round(10 * u));
  const limit = Math.round(126 * u) + 1;
  while (4 * h + 3 * g > limit) {
    if (g > 1 && (g - 10 * u >= h - 24 * u || h <= 2)) g--;
    else if (h > 1) h--;
    else break;
  }
  const w = Math.max(4, Math.round(116 * u));
  const short = Math.max(2, Math.round(80 * u));
  const head = Math.max(1, Math.round(32 * u));
  const mid = w - head - g;
  const top = Math.floor((size - (4 * h + 3 * g)) / 2);
  const left = Math.floor((size - w) / 2);
  const r = h >= 4 ? h / 2 : 0;
  const y = (i: number) => top + i * (h + g);
  return [
    { x: left, y: y(0), w: short, h, r, head: false },
    { x: left, y: y(1), w, h, r, head: false },
    { x: left, y: y(2), w: mid, h, r: 0, head: false },
    { x: left + mid + g, y: y(2), w: w - mid - g, h, r, head: true },
    { x: left, y: y(3), w: short, h, r, head: false },
  ];
}

/**
 * Below 32 px a full-bleed tile (radius 0.219 × size) with the mark 0.625 × size wide and no
 * hairline; from 32 px the tile is inset by 8/256 with radius 52/256, a hairline of
 * max(1, 1.5/256 × size), and the mark 116/256 of the size.
 */
export function brandLayout(size: number): BrandLayout {
  const s = Math.max(1, Math.round(size));
  if (s < 32) {
    return { x0: 0, x1: s, radius: (3.5 / 16) * s, hairline: 0, bars: fit(s, (0.625 * s) / 116) };
  }
  return {
    x0: (8 / 256) * s,
    x1: (248 / 256) * s,
    radius: (52 / 256) * s,
    hairline: Math.max(1, (1.5 / 256) * s),
    bars: fit(s, s / 256),
  };
}

/** A bar as a path: square left end, half-round right end when it has a radius. */
export function barPath(b: BrandBar): string {
  if (b.r <= 0) return `M${b.x} ${b.y}h${b.w}v${b.h}h${-b.w}z`;
  return `M${b.x} ${b.y}h${b.w - b.r}a${b.r} ${b.r} 0 0 1 0 ${b.h}h${-(b.w - b.r)}z`;
}

const SVG_NS = 'http://www.w3.org/2000/svg';

function el(doc: Document, name: string, attrs: Record<string, string | number>): SVGElement {
  const e = doc.createElementNS(SVG_NS, name);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
  return e;
}

/**
 * The mark as an `<svg>` of `size` CSS pixels: decorative (aria-hidden) unless it has a `title`,
 * as where the word "Downex" sits beside it.
 */
export function brandMark(doc: Document, size: number, title?: string): SVGSVGElement {
  const px = Math.max(1, Math.round(size));
  const l = brandLayout(px);
  const svg = el(doc, 'svg', { class: 'brand-mark', width: px, height: px, viewBox: `0 0 ${px} ${px}`, focusable: 'false' }) as SVGSVGElement;
  if (title) {
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', title);
  } else {
    svg.setAttribute('aria-hidden', 'true');
  }
  const side = l.x1 - l.x0;
  if (l.hairline > 0) {
    svg.append(el(doc, 'rect', { x: l.x0, y: l.x0, width: side, height: side, rx: l.radius, fill: 'var(--brand-hairline, #34403a)' }));
    const inner = side - 2 * l.hairline;
    svg.append(
      el(doc, 'rect', {
        x: l.x0 + l.hairline,
        y: l.x0 + l.hairline,
        width: inner,
        height: inner,
        rx: Math.max(0, l.radius - l.hairline),
        fill: 'var(--brand-tile, #1a221e)',
      }),
    );
  } else {
    svg.append(el(doc, 'rect', { x: l.x0, y: l.x0, width: side, height: side, rx: l.radius, fill: 'var(--brand-tile, #1a221e)' }));
    // A 1 px inner ring in the dark theme only (--brand-ring), so the tile keeps its silhouette on the dark chrome.
    svg.append(
      el(doc, 'rect', {
        class: 'ring',
        x: l.x0 + 0.5,
        y: l.x0 + 0.5,
        width: side - 1,
        height: side - 1,
        rx: Math.max(0, l.radius - 0.5),
        fill: 'none',
        stroke: 'var(--brand-ring, transparent)',
        'stroke-width': 1,
      }),
    );
  }
  for (const b of l.bars) {
    svg.append(el(doc, 'path', { d: barPath(b), fill: b.head ? 'var(--brand-head, #cef1e0)' : 'var(--brand-bar, #93e0ba)' }));
  }
  return svg;
}

/** Fills every `[data-brand-mark="<size>"]` placeholder under `root` with the mark (once). */
export function mountBrandMarks(root: ParentNode = document): void {
  const doc = root instanceof Document ? root : (root as Node).ownerDocument ?? document;
  for (const host of root.querySelectorAll<HTMLElement>('[data-brand-mark]')) {
    if (host.firstElementChild) continue;
    const size = Number(host.dataset.brandMark) || 22;
    host.append(brandMark(doc, size));
  }
}
